WITH with_windows AS (SELECT id, store_id, revenue, CORR(revenue, units) OVER (PARTITION BY store_id) corr_revenue_units, SUM(units) OVER (PARTITION BY store_id, product_id ORDER BY units, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_units, LEAD(units, 1) OVER (PARTITION BY product_id ORDER BY sale_date, id) next_units, ROW_NUMBER() OVER (ORDER BY sale_date, id) row_seq, AVG(revenue) OVER (PARTITION BY product_id, store_id ORDER BY sale_date, id ROWS BETWEEN 3 PRECEDING AND 1 PRECEDING) revenue_avg_3_prior FROM store_sales) SELECT s.id, s.store_id, s.corr_revenue_units, s.next_units, s.revenue_avg_3_prior, (SELECT SUM(o2.discount) FROM orders o2 WHERE o2.store_id = s.store_id) AS sum_order_discount FROM with_windows s ORDER BY corr_revenue_units DESC
